-- Stage updated project knowledge as pending review (do NOT touch content directly)
UPDATE public.knowledge_documents
SET
  pending_content = convert_from(decode('', 'base64'), 'UTF8'),
  pending_summary = 'Backfill missing knowledge: updated edge functions/tables/routes lists, two-source internal notes model, manual_messages dedup rule, Slack-import auto-navigate, canonical owners list (Joel/Kristina/Sam/CSM/Eren/Tine).',
  pending_at = now()
WHERE id = 'project-knowledge';
